// @FIGURE_CODE_BEGIN
(function(){
var W=900,H=500;
var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);

// World coords: V at x=0, object to the left (negative x), behind mirror to the right
var xDom=[-4.8,2.8], yDom=[-3.2,3.2];
var margin=30;

function sx(wx){return margin+(wx-xDom[0])*(W-2*margin)/(xDom[1]-xDom[0]);}
function sy(wy){return H-margin-(wy-yDom[0])*(H-2*margin)/(yDom[1]-yDom[0]);}

// State
var state={mirrorType:'Concave',objectDistance:2.5,highlightRay:0};
var f=1; // focal length magnitude

// Layers
var gAxis=draw.group();
var gMirror=draw.group();
var gPoints=draw.group();
var gRays=draw.group();
var gImage=draw.group();
var gLabels=draw.group();
var gEye=draw.group();

function getF(){return state.mirrorType==='Concave'?f:-f;}
function getC(){return 2*getF();}
function getDi(){
  var do_=state.objectDistance, ff=getF();
  return (do_*ff)/(do_-ff);
}
function getM(){
  var di=getDi(), do_=state.objectDistance;
  return -di/do_;
}

function mirrorArcPoints(){
  var cx=getC(), R=2*f;
  var pts=[];
  var n=40;
  if(state.mirrorType==='Concave'){
    // center at C (negative x), arc from -35° to +35°
    for(var i=0;i<=n;i++){
      var th=(-35+70*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  } else {
    // center at C (positive x), arc from 145° to 215°
    for(var i=0;i<=n;i++){
      var th=(145+70*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  }
  return pts;
}

function drawAll(){
  gAxis.clear();gMirror.clear();gPoints.clear();gRays.clear();gImage.clear();gLabels.clear();gEye.clear();

  var do_=state.objectDistance;
  var ff=getF();
  var cc=getC();
  var di=getDi();
  var m=getM();
  var h=1; // object height
  var hi=m*h; // image height

  // Object position
  var objX=-do_;
  // Image position
  var imgX=-di;

  // --- Axis ---
  gAxis.line(sx(xDom[0]),sy(0),sx(xDom[1]),sy(0)).stroke({color:'#333',width:1.5});

  // --- Mirror arc ---
  var arcPts=mirrorArcPoints();
  var arcStr=arcPts.map(function(p){return sx(p[0])+','+sy(p[1]);}).join(' ');
  gMirror.polyline(arcStr).fill('none').stroke({color:'#b8d4e8',width:6,linecap:'round'});
  gMirror.polyline(arcStr).fill('none').stroke({color:'#8ab8d8',width:2,linecap:'round'});

  // --- Points on axis ---
  // V
  gPoints.circle(6).cx(sx(0)).cy(sy(0)).fill('#333');
  gLabels.text('V').attr({x:sx(0)+4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});

  // F
  var fX=state.mirrorType==='Concave'?-f:f;
  gPoints.circle(6).cx(sx(fX)).cy(sy(0)).fill('#c00');
  gLabels.text('F').attr({x:sx(fX)-4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#c00'});

  // C
  var cX=state.mirrorType==='Concave'?-2*f:2*f;
  gPoints.circle(6).cx(sx(cX)).cy(sy(0)).fill('#333');
  gLabels.text('C').attr({x:sx(cX)-4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});

  // --- Object arrow ---
  var objTipY=h;
  gRays.line(sx(objX),sy(0),sx(objX),sy(objTipY)).stroke({color:'#cc2222',width:3});
  // arrowhead
  var ahx=sx(objX),ahy=sy(objTipY);
  gRays.polygon((ahx-5)+','+(ahy+10)+' '+ahx+','+ahy+' '+(ahx+5)+','+(ahy+10)).fill('#cc2222');
  gLabels.text('Q').attr({x:sx(objX)-14,y:sy(objTipY)-4,'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text('P').attr({x:sx(objX)-4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text('Object').attr({x:sx(objX)-40,y:sy(objTipY/2),'font-size':12,fill:'#333'});

  // --- Image arrow ---
  var imgTipY=hi;
  var isVirtual=di<0;
  var imgDash=isVirtual?'5,4':'none';
  gImage.line(sx(imgX),sy(0),sx(imgX),sy(imgTipY)).stroke({color:'#cc2222',width:3,'stroke-dasharray':imgDash});
  // arrowhead for image
  var ihx=sx(imgX),ihy=sy(imgTipY);
  if(imgTipY<0){
    gImage.polygon((ihx-5)+','+(ihy-10)+' '+ihx+','+ihy+' '+(ihx+5)+','+(ihy-10)).fill('#cc2222');
  } else {
    gImage.polygon((ihx-5)+','+(ihy+10)+' '+ihx+','+ihy+' '+(ihx+5)+','+(ihy+10)).fill('#cc2222');
  }
  gLabels.text("Q'").attr({x:sx(imgX)+6,y:sy(imgTipY)+(imgTipY>0?-4:14),'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text("P'").attr({x:sx(imgX)+6,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text('Image').attr({x:sx(imgX)+10,y:sy(imgTipY/2),'font-size':12,fill:'#333'});

  // --- Rays ---
  var rayColors=['#1a7abf','#cc2222','#7744aa','#55aa33'];
  var rayData=computeRays(do_,h,ff,cc,di,m,imgX,imgTipY);

  for(var r=0;r<4;r++){
    var rd=rayData[r];
    var col=rayColors[r];
    var alpha=1;
    var lw=2.5;
    if(state.highlightRay>0){
      if(state.highlightRay===r+1){alpha=1;lw=3.5;}
      else{alpha=0.15;lw=1.5;}
    }
    var grp=gRays.group().opacity(alpha);

    // Incident ray
    grp.line(sx(rd.inc[0][0]),sy(rd.inc[0][1]),sx(rd.inc[1][0]),sy(rd.inc[1][1]))
      .stroke({color:col,width:lw});
    // arrow on incident
    drawArrow(grp,rd.inc[0],rd.inc[1],col,lw);

    // Reflected ray (solid part)
    if(rd.refl){
      grp.line(sx(rd.refl[0][0]),sy(rd.refl[0][1]),sx(rd.refl[1][0]),sy(rd.refl[1][1]))
        .stroke({color:col,width:lw});
      drawArrow(grp,rd.refl[0],rd.refl[1],col,lw);
    }

    // Dashed extension (for virtual image)
    if(rd.ext){
      grp.line(sx(rd.ext[0][0]),sy(rd.ext[0][1]),sx(rd.ext[1][0]),sy(rd.ext[1][1]))
        .stroke({color:col,width:lw*0.7,'stroke-dasharray':'6,4'});
    }

    // Number label
    var lblPos=rd.labelPos;
    var lbl=grp.text(''+(r+1)).attr({x:sx(lblPos[0]),y:sy(lblPos[1]),'font-size':13,'font-weight':'bold',fill:col});
    lbl.css('cursor','pointer');
    lbl.on('click',function(rr){return function(){
      state.highlightRay=(state.highlightRay===rr+1)?0:rr+1;
      document.getElementById('rayHighlightInput').value=state.highlightRay;
      drawAll();
    };}(r));
  }

  // --- Right angle mark for ray 3 ---
