  } else {
    sqPts=[[r3hit[0],r3hit[1]+sqSize],[r3hit[0]-sqSize,r3hit[1]+sqSize],[r3hit[0]-sqSize,r3hit[1]]];
  }
  var sqStr=sqPts.map(function(p){return sx(p[0])+','+sy(p[1]);}).join(' ');
  gRays.polyline(sqStr).fill('none').stroke({color:'#333',width:1});

  // --- Eye icon ---
  drawEye(sx(-do_-0.8),sy(-1.5));
}

function drawArrow(grp,from,to,col,lw){
  var dx=to[0]-from[0],dy=to[1]-from[1];
  var len=Math.sqrt(dx*dx+dy*dy);
  if(len<0.01)return;
  var ux=dx/len,uy=dy/len;
  var mid=[from[0]+dx*0.55,from[1]+dy*0.55];
  var sz=0.06;
  var px=-uy*sz,py=ux*sz;
  var tip=[mid[0]+ux*sz*1.5,mid[1]+uy*sz*1.5];
  var b1=[mid[0]-ux*sz*0.5+px,mid[1]-uy*sz*0.5+py];
  var b2=[mid[0]-ux*sz*0.5-px,mid[1]-uy*sz*0.5-py];
  grp.polygon(sx(tip[0])+','+sy(tip[1])+' '+sx(b1[0])+','+sy(b1[1])+' '+sx(b2[0])+','+sy(b2[1])).fill(col);
}

function computeRays(do_,h,ff,cc,di,m,imgX,imgTipY){
  var rays=[];
  var objX=-do_;
  var isVirtual=di<0;
  var concave=state.mirrorType==='Concave';

  // Ray 1: parallel to axis, reflects through F (concave) or as if from F (convex)
  var hit1=[0,h];
  var refl1end,ext1=null;
  if(concave){
    // reflected through F(-f,0) and beyond to image
    var fPt=[-f,0];
    var dir=[fPt[0]-hit1[0],fPt[1]-hit1[1]];
    var t=2.5;
    refl1end=[hit1[0]+dir[0]*t,hit1[1]+dir[1]*t];
    if(isVirtual){
      ext1=[hit1,imgX!==undefined?[imgX,imgTipY]:[hit1[0]-1,hit1[1]]];
      // extension from hit point backward through F to image
      ext1=[hit1,[imgX,imgTipY]];
      refl1end=[hit1[0]+dir[0]*1.2,hit1[1]+dir[1]*1.2];
    }
  } else {
    // convex: reflects as if from F(+f,0)
    var fPt=[f,0];
    var dir=[hit1[0]-fPt[0],hit1[1]-fPt[1]]; // away from F
    var len=Math.sqrt(dir[0]*dir[0]+dir[1]*dir[1]);
    dir=[dir[0]/len,dir[1]/len];
    refl1end=[hit1[0]+dir[0]*2.5,hit1[1]+dir[1]*2.5];
    ext1=[hit1,[imgX,imgTipY]];
  }
  rays.push({inc:[[objX,h],hit1],refl:[hit1,refl1end],ext:ext1,labelPos:[(objX+hit1[0])/2,h+0.15]});

  // Ray 2: through F, reflects parallel
  var hit2y, hit2;
  if(concave){
    hit2y=h*f/(f-do_);
    hit2=[0,hit2y];
    var refl2end=[hit2[0]-3,hit2[1]];
    var ext2=isVirtual?[hit2,[imgX,imgTipY]]:null;
    if(isVirtual)refl2end=[hit2[0]-1.5,hit2[1]];
  } else {
    hit2y=h*f/(f+do_);
    hit2=[0,hit2y];
    var refl2end=[hit2[0]-3,hit2[1]];
    var ext2=[hit2,[imgX,imgTipY]];
    refl2end=[hit2[0]-1.5,hit2[1]];
  }
  rays.push({inc:[[objX,h],hit2],refl:[hit2,refl2end],ext:ext2,labelPos:[(objX)/2,h*0.55]});

  // Ray 3: through C, reflects back on itself
  var hit3y, hit3;
  if(concave){
    hit3y=2*h*f/(2*f-do_);
    hit3=[0,hit3y];
    // reflected back along same line
    var dir3=[objX-hit3[0],h-hit3[1]];
    var len3=Math.sqrt(dir3[0]*dir3[0]+dir3[1]*dir3[1]);
    dir3=[dir3[0]/len3,dir3[1]/len3];
    var refl3end=[hit3[0]+dir3[0]*2.5,hit3[1]+dir3[1]*2.5];
    var ext3=isVirtual?[hit3,[imgX,imgTipY]]:null;
    if(isVirtual)refl3end=[hit3[0]+dir3[0]*1.2,hit3[1]+dir3[1]*1.2];
  } else {
    hit3y=2*h*f/(2*f+do_);
    hit3=[0,hit3y];
    var dir3=[objX-hit3[0],h-hit3[1]];
    var len3=Math.sqrt(dir3[0]*dir3[0]+dir3[1]*dir3[1]);
    dir3=[dir3[0]/len3,dir3[1]/len3];
    var refl3end=[hit3[0]+dir3[0]*2.5,hit3[1]+dir3[1]*2.5];
    var ext3=[hit3,[imgX,imgTipY]];
    refl3end=[hit3[0]+dir3[0]*1.2,hit3[1]+dir3[1]*1.2];
  }
  rays.push({inc:[[objX,h],hit3],refl:[hit3,refl3end],ext:ext3,labelPos:[(objX+hit3[0])*0.4,h*0.75]});

  // Ray 4: hits V, reflects symmetrically
  var hit4=[0,0];
  var dir4=[-do_,-h]; // reflected direction (lower-left)
  var len4=Math.sqrt(dir4[0]*dir4[0]+dir4[1]*dir4[1]);
  dir4=[dir4[0]/len4,dir4[1]/len4];
  var refl4end=[hit4[0]+dir4[0]*3,hit4[1]+dir4[1]*3];
  var ext4=isVirtual?[hit4,[imgX,imgTipY]]:null;
  if(isVirtual)refl4end=[hit4[0]+dir4[0]*1.2,hit4[1]+dir4[1]*1.2];
  rays.push({inc:[[objX,h],hit4],refl:[hit4,refl4end],ext:ext4,labelPos:[(objX)*0.5,-h*0.35]});

  return rays;
}

function drawEye(ex,ey){
  var s=18;
  gEye.ellipse(s*2,s).cx(ex).cy(ey).fill('none').stroke({color:'#333',width:1.5});
  gEye.circle(s*0.5).cx(ex).cy(ey).fill('#333');
