  gEye.line(ex-s,ey-s*0.3,ex-s*1.3,ey-s*0.7).stroke({color:'#333',width:1});
  gEye.line(ex-s*0.5,ey-s*0.45,ex-s*0.6,ey-s*0.9).stroke({color:'#333',width:1});
  gEye.line(ex,ey-s*0.5,ex,ey-s*1).stroke({color:'#333',width:1});
}

