var gPoints=draw.group();
var gRays=draw.group();
var gImage=draw.group();
var gLabels=draw.group();
var gEye=draw.group();

function getF(){return state.mirrorType==='Concave'?f:-f;}
function getC(){return 2*getF();}
function getDi(){
  var do_=state.objectDistance, ff=getF();
  return (do_*ff)/(do_-ff);
}
function getM(){
  var di=getDi(), do_=state.objectDistance;
  return -di/do_;
}

function mirrorArcPoints(){
  var cx=getC(), R=2*f;
  var pts=[];
  var n=40;
  if(state.mirrorType==='Concave'){
    // center at C (negative x), arc from -35° to +35°
    for(var i=0;i<=n;i++){
      var th=(-35+70*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  } else {
    // center at C (positive x), arc from 145° to 215°
    for(var i=0;i<=n;i++){
      var th=(145+70*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  }
  return pts;
}

function drawAll(){
  gAxis.clear();gMirror.clear();gPoints.clear();gRays.clear();gImage.clear();gLabels.clear();gEye.clear();

  var do_=state.objectDistance;
  var ff=getF();
  var cc=getC();
  var di=getDi();
  var m=getM();
  var h=1; // object height
  var hi=m*h; // image height

  // Object position
  var objX=-do_;
  // Image position
  var imgX=-di;

  // --- Axis ---
  gAxis.line(sx(xDom[0]),sy(0),sx(xDom[1]),sy(0)).stroke({color:'#333',width:1.5});

  // --- Mirror arc ---
  var arcPts=mirrorArcPoints();
  var arcStr=arcPts.map(function(p){return sx(p[0])+','+sy(p[1]);}).join(' ');
  gMirror.polyline(arcStr).fill('none').stroke({color:'#b8d4e8',width:6,linecap:'round'});
  gMirror.polyline(arcStr).fill('none').stroke({color:'#8ab8d8',width:2,linecap:'round'});

  // --- Points on axis ---
  // V
  gPoints.circle(6).cx(sx(0)).cy(sy(0)).fill('#333');
  gLabels.text('V').attr({x:sx(0)+4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});

  // F
  var fX=state.mirrorType==='Concave'?-f:f;
  gPoints.circle(6).cx(sx(fX)).cy(sy(0)).fill('#c00');
  gLabels.text('F').attr({x:sx(fX)-4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#c00'});

  // C
  var cX=state.mirrorType==='Concave'?-2*f:2*f;
  gPoints.circle(6).cx(sx(cX)).cy(sy(0)).fill('#333');
  gLabels.text('C').attr({x:sx(cX)-4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});

  // --- Object arrow ---
  var objTipY=h;
  gRays.line(sx(objX),sy(0),sx(objX),sy(objTipY)).stroke({color:'#cc2222',width:3});
  // arrowhead
  var ahx=sx(objX),ahy=sy(objTipY);
  gRays.polygon((ahx-5)+','+(ahy+10)+' '+ahx+','+ahy+' '+(ahx+5)+','+(ahy+10)).fill('#cc2222');
  gLabels.text('Q').attr({x:sx(objX)-14,y:sy(objTipY)-4,'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text('P').attr({x:sx(objX)-4,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text('Object').attr({x:sx(objX)-40,y:sy(objTipY/2),'font-size':12,fill:'#333'});

  // --- Image arrow ---
  var imgTipY=hi;
  var isVirtual=di<0;
  var imgDash=isVirtual?'5,4':'none';
  gImage.line(sx(imgX),sy(0),sx(imgX),sy(imgTipY)).stroke({color:'#cc2222',width:3,'stroke-dasharray':imgDash});
  // arrowhead for image
  var ihx=sx(imgX),ihy=sy(imgTipY);
  if(imgTipY<0){
    gImage.polygon((ihx-5)+','+(ihy-10)+' '+ihx+','+ihy+' '+(ihx+5)+','+(ihy-10)).fill('#cc2222');
  } else {
    gImage.polygon((ihx-5)+','+(ihy+10)+' '+ihx+','+ihy+' '+(ihx+5)+','+(ihy+10)).fill('#cc2222');
  }
  gLabels.text("Q'").attr({x:sx(imgX)+6,y:sy(imgTipY)+(imgTipY>0?-4:14),'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text("P'").attr({x:sx(imgX)+6,y:sy(0)+14,'font-size':13,'font-weight':'bold',fill:'#333'});
  gLabels.text('Image').attr({x:sx(imgX)+10,y:sy(imgTipY/2),'font-size':12,fill:'#333'});

  // --- Rays ---
  var rayColors=['#1a7abf','#cc2222','#7744aa','#55aa33'];
  var rayData=computeRays(do_,h,ff,cc,di,m,imgX,imgTipY);

  for(var r=0;r<4;r++){
    var rd=rayData[r];
    var col=rayColors[r];
    var alpha=1;
    var lw=2.5;
    if(state.highlightRay>0){
      if(state.highlightRay===r+1){alpha=1;lw=3.5;}
      else{alpha=0.15;lw=1.5;}
    }
    var grp=gRays.group().opacity(alpha);

    // Incident ray
    grp.line(sx(rd.inc[0][0]),sy(rd.inc[0][1]),sx(rd.inc[1][0]),sy(rd.inc[1][1]))
      .stroke({color:col,width:lw});
    // arrow on incident
    drawArrow(grp,rd.inc[0],rd.inc[1],col,lw);

    // Reflected ray (solid part)
    if(rd.refl){
      grp.line(sx(rd.refl[0][0]),sy(rd.refl[0][1]),sx(rd.refl[1][0]),sy(rd.refl[1][1]))
        .stroke({color:col,width:lw});
      drawArrow(grp,rd.refl[0],rd.refl[1],col,lw);
    }

    // Dashed extension (for virtual image)
    if(rd.ext){
      grp.line(sx(rd.ext[0][0]),sy(rd.ext[0][1]),sx(rd.ext[1][0]),sy(rd.ext[1][1]))
        .stroke({color:col,width:lw*0.7,'stroke-dasharray':'6,4'});
    }

    // Number label
    var lblPos=rd.labelPos;
    var lbl=grp.text(''+(r+1)).attr({x:sx(lblPos[0]),y:sy(lblPos[1]),'font-size':13,'font-weight':'bold',fill:col});
    lbl.css('cursor','pointer');
    lbl.on('click',function(rr){return function(){
      state.highlightRay=(state.highlightRay===rr+1)?0:rr+1;
      document.getElementById('rayHighlightInput').value=state.highlightRay;
      drawAll();
    };}(r));
  }

  // --- Right angle mark for ray 3 ---
  var r3hit=rayData[2].inc[1];
  var sqSize=0.08;
  var sqPts;
  if(state.mirrorType==='Concave'){
    sqPts=[[r3hit[0],r3hit[1]+sqSize],[r3hit[0]+sqSize,r3hit[1]+sqSize],[r3hit[0]+sqSize,r3hit[1]]];
  } else {
    sqPts=[[r3hit[0],r3hit[1]+sqSize],[r3hit[0]-sqSize,r3hit[1]+sqSize],[r3hit[0]-sqSize,r3hit[1]]];
  }
  var sqStr=sqPts.map(function(p){return sx(p[0])+','+sy(p[1]);}).join(' ');
  gRays.polyline(sqStr).fill('none').stroke({color:'#333',width:1});

  // --- Eye icon ---
  drawEye(sx(-do_-0.8),sy(-1.5));
}

function drawArrow(grp,from,to,col,lw){
  var dx=to[0]-from[0],dy=to[1]-from[1];
  var len=Math.sqrt(dx*dx+dy*dy);
  if(len<0.01)return;
  var ux=dx/len,uy=dy/len;
  var mid=[from[0]+dx*0.55,from[1]+dy*0.55];
  var sz=0.06;
  var px=-uy*sz,py=ux*sz;
  var tip=[mid[0]+ux*sz*1.5,mid[1]+uy*sz*1.5];
  var b1=[mid[0]-ux*sz*0.5+px,mid[1]-uy*sz*0.5+py];
  var b2=[mid[0]-ux*sz*0.5-px,mid[1]-uy*sz*0.5-py];
  grp.polygon(sx(tip[0])+','+sy(tip[1])+' '+sx(b1[0])+','+sy(b1[1])+' '+sx(b2[0])+','+sy(b2[1])).fill(col);
}

function computeRays(do_,h,ff,cc,di,m,imgX,imgTipY){
  var rays=[];
  var objX=-do_;
  var isVirtual=di<0;
  var concave=state.mirrorType==='Concave';

  // Ray 1: parallel to axis, reflects through F (concave) or as if from F (convex)
  var hit1=[0,h];
  var refl1end,ext1=null;
  if(concave){
    // reflected through F(-f,0) and beyond to image
    var fPt=[-f,0];
    var dir=[fPt[0]-hit1[0],fPt[1]-hit1[1]];
    var t=2.5;
    refl1end=[hit1[0]+dir[0]*t,hit1[1]+dir[1]*t];
    if(isVirtual){
      ext1=[hit1,imgX!==undefined?[imgX,imgTipY]:[hit1[0]-1,hit1[1]]];
      // extension from hit point backward through F to image
      ext1=[hit1,[imgX,imgTipY]];
      refl1end=[hit1[0]+dir[0]*1.2,hit1[1]+dir[1]*1.2];
    }
  } else {
    // convex: reflects as if from F(+f,0)
    var fPt=[f,0];
    var dir=[hit1[0]-fPt[0],hit1[1]-fPt[1]]; // away from F
    var len=Math.sqrt(dir[0]*dir[0]+dir[1]*dir[1]);
    dir=[dir[0]/len,dir[1]/len];
    refl1end=[hit1[0]+dir[0]*2.5,hit1[1]+dir[1]*2.5];
    ext1=[hit1,[imgX,imgTipY]];
  }
  rays.push({inc:[[objX,h],hit1],refl:[hit1,refl1end],ext:ext1,labelPos:[(objX+hit1[0])/2,h+0.15]});

  // Ray 2: through F, reflects parallel
  var hit2y, hit2;
  if(concave){
    hit2y=h*f/(f-do_);
    hit2=[0,hit2y];
    var refl2end=[hit2[0]-3,hit2[1]];
    var ext2=isVirtual?[hit2,[imgX,imgTipY]]:null;
    if(isVirtual)refl2end=[hit2[0]-1.5,hit2[1]];
  } else {
    hit2y=h*f/(f+do_);
    hit2=[0,hit2y];
    var refl2end=[hit2[0]-3,hit2[1]];
    var ext2=[hit2,[imgX,imgTipY]];
    refl2end=[hit2[0]-1.5,hit2[1]];
  }
  rays.push({inc:[[objX,h],hit2],refl:[hit2,refl2end],ext:ext2,labelPos:[(objX)/2,h*0.55]});

  // Ray 3: through C, reflects back on itself
  var hit3y, hit3;
  if(concave){
    hit3y=2*h*f/(2*f-do_);
    hit3=[0,hit3y];
    // reflected back along same line
    var dir3=[objX-hit3[0],h-hit3[1]];
    var len3=Math.sqrt(dir3[0]*dir3[0]+dir3[1]*dir3[1]);
    dir3=[dir3[0]/len3,dir3[1]/len3];
    var refl3end=[hit3[0]+dir3[0]*2.5,hit3[1]+dir3[1]*2.5];
    var ext3=isVirtual?[hit3,[imgX,imgTipY]]:null;
    if(isVirtual)refl3end=[hit3[0]+dir3[0]*1.2,hit3[1]+dir3[1]*1.2];
  } else {
    hit3y=2*h*f/(2*f+do_);
    hit3=[0,hit3y];
    var dir3=[objX-hit3[0],h-hit3[1]];
    var len3=Math.sqrt(dir3[0]*dir3[0]+dir3[1]*dir3[1]);
    dir3=[dir3[0]/len3,dir3[1]/len3];
    var refl3end=[hit3[0]+dir3[0]*2.5,hit3[1]+dir3[1]*2.5];
    var ext3=[hit3,[imgX,imgTipY]];
    refl3end=[hit3[0]+dir3[0]*1.2,hit3[1]+dir3[1]*1.2];
  }
  rays.push({inc:[[objX,h],hit3],refl:[hit3,refl3end],ext:ext3,labelPos:[(objX+hit3[0])*0.4,h*0.75]});

  // Ray 4: hits V, reflects symmetrically
  var hit4=[0,0];
  var dir4=[-do_,-h]; // reflected direction (lower-left)
  var len4=Math.sqrt(dir4[0]*dir4[0]+dir4[1]*dir4[1]);
  dir4=[dir4[0]/len4,dir4[1]/len4];
  var refl4end=[hit4[0]+dir4[0]*3,hit4[1]+dir4[1]*3];
  var ext4=isVirtual?[hit4,[imgX,imgTipY]]:null;
  if(isVirtual)refl4end=[hit4[0]+dir4[0]*1.2,hit4[1]+dir4[1]*1.2];
  rays.push({inc:[[objX,h],hit4],refl:[hit4,refl4end],ext:ext4,labelPos:[(objX)*0.5,-h*0.35]});

  return rays;
}

function drawEye(ex,ey){
  var s=18;
  gEye.ellipse(s*2,s).cx(ex).cy(ey).fill('none').stroke({color:'#333',width:1.5});
  gEye.circle(s*0.5).cx(ex).cy(ey).fill('#333');
  // eyelashes
  gEye.line(ex-s,ey-s*0.3,ex-s*1.3,ey-s*0.7).stroke({color:'#333',width:1});
  gEye.line(ex-s*0.5,ey-s*0.45,ex-s*0.6,ey-s*0.9).stroke({color:'#333',width:1});
  gEye.line(ex,ey-s*0.5,ex,ey-s*1).stroke({color:'#333',width:1});
}

// --- Controls ---
window.toggle_mirrorType=function(on){
  state.mirrorType=on?'Convex':'Concave';
  drawAll();
};
window.update_objectDistance=function(v){
  state.objectDistance=v;
  drawAll();
};
window.update_rayHighlight=function(v){
  state.highlightRay=v;
  drawAll();
};

// --- Demo steps ---
var steps=[
  {title:'Concave mirror, object beyond C',narration:'With the object far from a concave mirror, all four color-coded rays leave the tip Q and truly cross at Q\' in front of the mirror, forming a real, inverted, reduced image between C and F.',state:{mirrorType:'Concave',objectDistance:2.5,highlightRay:0}},
  {title:'Isolate one ray rule',narration:'Click ray 1 (blue): it travels parallel to the axis and reflects straight through F. Clicking each numbered ray in turn reveals the one geometric rule behind it.',state:{mirrorType:'Concave',objectDistance:2.5,highlightRay:1}},
  {title:'Move the object inside F',narration:'Drag the slider so the object sits between F and the mirror: the reflected rays now diverge, and only their dashed backward extensions meet behind the mirror, producing a virtual, upright, magnified image.',state:{mirrorType:'Concave',objectDistance:0.6,highlightRay:0}},
  {title:'Convex mirror always virtual',narration:'Toggle to the convex mirror: F and C move behind the arc, the reflected rays always spread apart, and their dashed extensions meet at an upright, reduced virtual image behind the mirror.',state:{mirrorType:'Convex',objectDistance:2.5,highlightRay:0}}
];
var curStep=0;

function applyStep(i){
  curStep=i;
  var s=steps[i];
  state.mirrorType=s.state.mirrorType;
  state.objectDistance=s.state.objectDistance;
  state.highlightRay=s.state.highlightRay||0;
  document.getElementById('mirrorTypeInput').checked=(state.mirrorType==='Convex');
  document.getElementById('objectDistanceInput').value=state.objectDistance;
  document.getElementById('objectDistanceVal').value=state.objectDistance;
  document.getElementById('rayHighlightInput').value=state.highlightRay;
  document.getElementById('demoNarration').textContent=s.narration;
  document.getElementById('stepLabel').textContent=(i+1)+'/'+steps.length;
  drawAll();
}
window.prevStep=function(){if(curStep>0)applyStep(curStep-1);};
window.nextStep=function(){if(curStep<steps.length-1)applyStep(curStep+1);};

// Init
applyStep(0);
window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The image formed by a spherical mirror is located exactly where the principal rays (or their backward extensions) intersect, so a concave mirror can produce a real inverted image when rays truly converge or a virtual upright image when the object is inside the focal point, while a convex mirror always yields a virtual upright image because its reflected rays only ever diverge.
KEY INSIGHT (what students should walk away understanding): An image sits exactly where the principal rays intersect: when the rays themselves cross in front of the mirror the image is real and inverted, but when only their backward extensions cross behind the mirror the image is virtual and upright — concave mirrors can do both depending on object position, convex mirrors only the latter.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The image formed by a spherical mirror is located exactly where the principal rays (or their backward extensions) intersect, so a concave mirror can produce a real inverted image when rays truly converge or a virtual upright image when the object is inside the focal point, while a convex mirror always yields a virtual upright image because its reflected rays only ever diverge.",
  "figureType": "diagram",
  "elements": [
    "horizontal optical axis line",
    "spherical mirror drawn as a pale blue curved arc on the right (concave opening left in panel a, convex bulging left in panel b)",
    "vertex point V where the arc meets the axis, labeled V",
    "focal point F on the axis, labeled F (in front of mirror for concave, behind for convex)",
    "center of curvature C on the axis, labeled C (in front for concave, behind for convex)",
    "red upward object arrow with base P on the axis and tip Q, labeled Object",
    "red image arrow with base P' on the axis and tip Q', labeled Image (downward/inverted for concave real case, upward/upright for virtual cases)",
    "ray 1 (blue): from Q parallel to axis to mirror, reflected through F",
    "ray 2 (red): from Q through F to mirror, reflected parallel to axis",
    "ray 3 (purple): from Q toward C to mirror, reflected back on itself, with a small right-angle square at the mirror",
    "ray 4 (green): from Q to vertex V, reflected symmetrically across the axis",
    "number labels 1, 2, 3, 4 beside each ray",
    "dashed backward extensions of the reflected rays meeting at Q' behind the mirror (convex case and concave virtual case)",
    "small drawn eye icon at lower left looking toward the mirror",
    "panel captions (a) and (b)"
  ],
  "interactions": [
    {
      "id": "mirrorType",
      "type": "toggle",
      "label": "Mirror type",
      "options": [
        "Concave",
        "Convex"
      ],
      "default": "Concave",
      "teaches": "Switching mirror type flips where F and C sit and whether the reflected rays genuinely converge in front of the mirror (real image, concave) or spread apart so that only their dashed backward extensions meet behind it (virtual image, convex)"
    },
    {
      "id": "objectDistance",
      "type": "slider",
      "label": "Object distance from mirror",
      "range": [
        0.3,
        3.5,
        0.1
      ],
      "default": 2.5,
      "teaches": "Dragging the object along the axis moves, resizes, and flips the image: for a concave mirror the image is real and inverted when the object is outside F but becomes virtual, upright and magnified once the object crosses inside F; for a convex mirror the image stays virtual, upright and reduced at every position"
    },
    {
      "id": "rayHighlight",
      "type": "click",
      "teaches": "Selecting one numbered ray isolates its single construction rule (1: parallel in, through F out; 2: through F in, parallel out; 3: through C, returns on itself; 4: hits V, reflects symmetrically), so each rule can be read off the busy crossing diagram one at a time"
    }
  ],
  "demo_steps": [
    {
      "title": "Concave mirror, object beyond C",
      "narration": "With the object far from a concave mirror, all four color-coded rays leave the tip Q and truly cross at Q' in front of the mirror, forming a real, inverted, reduced image between C and F.",
      "state": {
        "mirrorType": "Concave",
        "objectDistance": 2.5
      }
    },
    {
      "title": "Isolate one ray rule",
      "narration": "Click ray 1 (blue): it travels parallel to the axis and reflects straight through F. Clicking each numbered ray in turn reveals the one geometric rule behind it, building up the construction ray by ray.",
      "state": {
        "mirrorType": "Concave",
        "objectDistance": 2.5
      }
    },
    {
      "title": "Move the object inside F",
      "narration": "Drag the slider so the object sits between F and the mirror: the reflected rays now diverge, and only their dashed backward extensions meet behind the mirror, producing a virtual, upright, magnified image.",
      "state": {
        "mirrorType": "Concave",
        "objectDistance": 0.6
      }
    },
    {
      "title": "Convex mirror always virtual",
      "narration": "Toggle to the convex mirror: F and C move behind the arc, the reflected rays always spread apart, and their dashed extensions meet at an upright, reduced virtual image behind the mirror no matter where the object is placed.",
      "state": {
        "mirrorType": "Convex",
        "objectDistance": 2.5
      }
    }
  ],
  "keyInsight": "An image sits exactly where the principal rays intersect: when the rays themselves cross in front of the mirror the image is real and inverted, but when only their backward extensions cross behind the mirror the image is virtual and upright — concave mirrors can do both depending on object position, convex mirrors only the latter.",
  "reconstructionNotes": "Lay out a single mirror panel at a time (per the toggle), not both stacked. Draw the optical axis horizontally with V at the mirror, then F and C along it (in front for concave, behind for convex). Object is a bold red upward arrow on the left labeled Object with base P and tip Q; image is a red arrow at P'/Q' labeled Image, drawn downward when real/inverted and upward when virtual/upright, with dashed segments for virtual images. Color the four rays consistently: ray 1 blue, ray 2 red, ray 3 purple, ray 4 green, each with its incident and reflected (or dashed extended) segment and a small number label; add a tiny right-angle square where ray 3 meets the mirror and a simple eye glyph at lower left. The mirror is a thin pale-blue arc. On slider change, recompute all four rays and the image arrow from the mirror equation so the convergence/divergence and the image's position, size and orientation update live; on ray click, dim the other three rays and brighten the selected one end to end."
}

