(function(){
var W=900,H=540;
var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);

var xDom=[-5.8,3.4], yDom=[-3.4,3.4];
var margin=38;

function sx(wx){return margin+(wx-xDom[0])*(W-2*margin)/(xDom[1]-xDom[0]);}
function sy(wy){return H-margin-(wy-yDom[0])*(H-2*margin)/(yDom[1]-yDom[0]);}

var state={mirrorType:'Concave',objectDistance:2.5,highlightRay:0};
var f=1;
var ARC_DEG=65;

var gAxis=draw.group();
var gMirror=draw.group();
var gRays=draw.group();
var gImage=draw.group();
var gLabels=draw.group();
var gEye=draw.group();

function getF(){return state.mirrorType==='Concave'?f:-f;}
function getC(){return 2*getF();}
function getDi(){
  var do_=state.objectDistance, ff=getF();
  var denom=do_-ff;
  if(Math.abs(denom)<0.01) return (denom>=0?1:-1)*999;
  return (do_*ff)/denom;
}
function getM(){
  var di=getDi(), do_=state.objectDistance;
  return -di/do_;
}

function mirrorArcPoints(){
  var cx=getC(), R=2*f, pts=[], n=60;
  if(state.mirrorType==='Concave'){
    for(var i=0;i<=n;i++){
      var th=(-ARC_DEG+2*ARC_DEG*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  } else {
    for(var i=0;i<=n;i++){
      var th=(180-ARC_DEG+2*ARC_DEG*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  }
  return pts;
}

function rayCircleHit(A,d,C,R){
  var ox=A[0]-C[0], oy=A[1]-C[1];
  var a=d[0]*d[0]+d[1]*d[1];
  if(a<1e-12) return null;
  var b=2*(ox*d[0]+oy*d[1]);
  var c=ox*ox+oy*oy-R*R;
  var disc=b*b-4*a*c;
  if(disc<0) return null;
  var sq=Math.sqrt(disc);
  var t1=(-b-sq)/(2*a), t2=(-b+sq)/(2*a);
  var t=null;
  if(t1>0.001) t=t1;
  else if(t2>0.001) t=t2;
  if(t===null) return null;
  return [A[0]+t*d[0], A[1]+t*d[1]];
}

function clipToArc(pt){
  var cx=getC(), R=2*f;
  var angle=Math.atan2(pt[1], pt[0]-cx);
  var deg=angle*180/Math.PI;
  if(state.mirrorType==='Concave'){
    if(deg>ARC_DEG) deg=ARC_DEG;
    if(deg<-ARC_DEG) deg=-ARC_DEG;
  } else {
    if(deg<0) deg+=360;
    var lo=180-ARC_DEG, hi=180+ARC_DEG;
    if(deg<lo) deg=lo;
    if(deg>hi) deg=hi;
  }
  var rad=deg*Math.PI/180;
  return [cx+R*Math.cos(rad), R*Math.sin(rad)];
}

function drawAll(){
  gAxis.clear();gMirror.clear();gRays.clear();gImage.clear();gLabels.clear();gEye.clear();

  var do_=state.objectDistance;
  var ff=getF();
  var cc=getC();
  var di=getDi();
  var m=getM();
  var h=1.2;
  var hi=m*h;
  var objX=-do_;
  var imgX=-di;
  var concave=state.mirrorType==='Concave';
  var isVirtual=di<0;
  var showImage=isFinite(di)&&Math.abs(di)<18;

  // Axis
  gAxis.line(sx(xDom[0]),sy(0),sx(xDom[1]),sy(0)).stroke({color:'#555',width:1.2});

  // Mirror arc
  var arcPts=mirrorArcPoints();
  var arcStr=arcPts.map(function(p){return sx(p[0])+','+sy(p[1]);}).join(' ');
  gMirror.polyline(arcStr).fill('none').stroke({color:'#d8ecf4',width:14,linecap:'round'});
  gMirror.polyline(arcStr).fill('none').stroke({color:'#89b8d4',width:3.5,linecap:'round'});

  // Axis points
  gAxis.circle(5).cx(sx(0)).cy(sy(0)).fill('#333');
  gLabels.text('V').attr({x:sx(0)+8,y:sy(0)+17,'font-size':14,'font-weight':'bold',fill:'#333'});

  var fX=concave?-f:f;
  gAxis.circle(5).cx(sx(fX)).cy(sy(0)).fill('#c00');
  gLabels.text('F').attr({x:sx(fX)-5,y:sy(0)+17,'font-size':14,'font-weight':'bold',fill:'#c00'});

  var cX=concave?-2*f:2*f;
  gAxis.circle(5).cx(sx(cX)).cy(sy(0)).fill('#333');
  gLabels.text('C').attr({x:sx(cX)-5,y:sy(0)+17,'font-size':14,'font-weight':'bold',fill:'#333'});

  // Object arrow
  gRays.line(sx(objX),sy(0),sx(objX),sy(h)).stroke({color:'#cc2222',width:4});
  var ahx=sx(objX),ahy=sy(h);
