function getF(){return state.mirrorType==='Concave'?f:-f;}
function getC(){return 2*getF();}
function getDi(){
  var do_=state.objectDistance, ff=getF();
  var denom=do_-ff;
  if(Math.abs(denom)<0.01) return (denom>=0?1:-1)*999;
  return (do_*ff)/denom;
}
function getM(){
  var di=getDi(), do_=state.objectDistance;
  return -di/do_;
}

function mirrorArcPoints(){
  var cx=getC(), R=2*f, pts=[], n=60;
  if(state.mirrorType==='Concave'){
    for(var i=0;i<=n;i++){
      var th=(-ARC_DEG+2*ARC_DEG*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  } else {
    for(var i=0;i<=n;i++){
      var th=(180-ARC_DEG+2*ARC_DEG*i/n)*Math.PI/180;
      pts.push([cx+R*Math.cos(th), R*Math.sin(th)]);
    }
  }
  return pts;
}

function rayCircleHit(A,d,C,R){
  var ox=A[0]-C[0], oy=A[1]-C[1];
  var a=d[0]*d[0]+d[1]*d[1];
  if(a<1e-12) return null;
  var b=2*(ox*d[0]+oy*d[1]);
  var c=ox*ox+oy*oy-R*R;
  var disc=b*b-4*a*c;
  if(disc<0) return null;
  var sq=Math.sqrt(disc);
  var t1=(-b-sq)/(2*a), t2=(-b+sq)/(2*a);
  var t=null;
  if(t1>0.001) t=t1;
  else if(t2>0.001) t=t2;
  if(t===null) return null;
  return [A[0]+t*d[0], A[1]+t*d[1]];
}

function clipToArc(pt){
  var cx=getC(), R=2*f;
  var angle=Math.atan2(pt[1], pt[0]-cx);
  var deg=angle*180/Math.PI;
  if(state.mirrorType==='Concave'){
    if(deg>ARC_DEG) deg=ARC_DEG;
    if(deg<-ARC_DEG) deg=-ARC_DEG;
  } else {
    if(deg<0) deg+=360;
    var lo=180-ARC_DEG, hi=180+ARC_DEG;
    if(deg<lo) deg=lo;
    if(deg>hi) deg=hi;
  }
  var rad=deg*Math.PI/180;
  return [cx+R*Math.cos(rad), R*Math.sin(rad)];
}

function drawAll(){
  gAxis.clear();gMirror.clear();gRays.clear();gImage.clear();gLabels.clear();gEye.clear();

  var do_=state.objectDistance;
  var ff=getF();
  var cc=getC();
  var di=getDi();
  var m=getM();
  var h=1.2;
  var hi=m*h;
  var objX=-do_;
  var imgX=-di;
  var concave=state.mirrorType==='Concave';
  var isVirtual=di<0;
  var showImage=isFinite(di)&&Math.abs(di)<18;

  // Axis
  gAxis.line(sx(xDom[0]),sy(0),sx(xDom[1]),sy(0)).stroke({color:'#555',width:1.2});

  // Mirror arc with hatching on back side
  var arcPts=mirrorArcPoints();
  var arcStr=arcPts.map(function(p){return sx(p[0])+','+sy(p[1]);}).join(' ');

  // Thick pale-blue backing
  gMirror.polyline(arcStr).fill('none').stroke({color:'#d8ecf4',width:16,linecap:'round'});
  // Main arc line
  gMirror.polyline(arcStr).fill('none').stroke({color:'#89b8d4',width:3.5,linecap:'round'});

  // Hatching on back side of mirror
  var nHatch=14;
  for(var i=1;i<nHatch;i++){
    var t=i/nHatch;
    var idx=Math.round(t*(arcPts.length-1));
    var pt=arcPts[idx];
    var cx2=getC(), R2=2*f;
    // Normal direction (pointing away from center = back side)
    var nx=pt[0]-cx2, ny=pt[1]-0;
    var nl=Math.sqrt(nx*nx+ny*ny);
    if(nl<0.01) continue;
    nx/=nl; ny/=nl;
    // Hatching: short lines going outward from back of arc at 45 degrees
    var hx=nx*0.18+ny*0.12, hy=ny*0.18-nx*0.12;
    var startX=pt[0]+nx*0.09, startY=pt[1]+ny*0.09;
    gMirror.line(sx(startX),sy(startY),sx(startX+hx),sy(startY+hy))
      .stroke({color:'#89b8d4',width:1.2,linecap:'round'});
  }

  // Axis points
  gAxis.circle(6).cx(sx(0)).cy(sy(0)).fill('#333');
  gLabels.text('V').attr({x:sx(0)+8,y:sy(0)+20,'font-size':15,'font-weight':'bold',fill:'#333'});

  var fX=concave?-f:f;
  gAxis.circle(6).cx(sx(fX)).cy(sy(0)).fill('#c00');
  gLabels.text('F').attr({x:sx(fX)-5,y:sy(0)+20,'font-size':15,'font-weight':'bold',fill:'#c00'});

  var cX=concave?-2*f:2*f;
  gAxis.circle(6).cx(sx(cX)).cy(sy(0)).fill('#333');
  gLabels.text('C').attr({x:sx(cX)-5,y:sy(0)+20,'font-size':15,'font-weight':'bold',fill:'#333'});

  // Object arrow
  gRays.line(sx(objX),sy(0),sx(objX),sy(h)).stroke({color:'#cc2222',width:4.5});
  var ahx=sx(objX),ahy=sy(h);
  gRays.polygon((ahx-8)+','+(ahy+16)+' '+ahx+','+ahy+' '+(ahx+8)+','+(ahy+16)).fill('#cc2222');
  gLabels.text('Q').attr({x:sx(objX)-20,y:sy(h)-10,'font-size':16,'font-weight':'bold',fill:'#333'});
  gLabels.text('P').attr({x:sx(objX)-5,y:sy(0)+20,'font-size':15,'font-weight':'bold',fill:'#333'});
  gLabels.text('Object').attr({x:sx(objX)-62,y:sy(h*0.5)+4,'font-size':13,fill:'#333'});

  // Image arrow
  if(showImage){
    var imgDash=isVirtual?'7,5':'none';
    gImage.line(sx(imgX),sy(0),sx(imgX),sy(hi)).stroke({color:'#cc2222',width:3.5,'stroke-dasharray':imgDash});
    var ihx=sx(imgX),ihy=sy(hi);
    if(hi<0){
      gImage.polygon((ihx-7)+','+(ihy-14)+' '+ihx+','+ihy+' '+(ihx+7)+','+(ihy-14)).fill('#cc2222');
    } else {
      gImage.polygon((ihx-7)+','+(ihy+14)+' '+ihx+','+ihy+' '+(ihx+7)+','+(ihy+14)).fill('#cc2222');
    }
    // Q' label - offset to avoid crowding
    var qLabelY = hi>0 ? sy(hi)-12 : sy(hi)+22;
    gLabels.text("Q'").attr({x:sx(imgX)+14,y:qLabelY,'font-size':15,'font-weight':'bold',fill:'#333'});
    // P' label - offset below axis
    gLabels.text("P'").attr({x:sx(imgX)+14,y:sy(0)+20,'font-size':15,'font-weight':'bold',fill:'#333'});
    // Image label with leader line
    var ilx=sx(imgX)+60, ily=sy(hi*0.3)+48;
    gLabels.text('Image').attr({x:ilx,y:ily,'font-size':14,fill:'#333'});
    var aex=sx(imgX)+16, aey=sy(hi*0.5);
    gLabels.path('M'+(ilx-4)+','+(ily-14)+' Q'+(ilx-24)+','+(ily-30)+' '+aex+','+aey)
      .fill('none').stroke({color:'#333',width:1.3});
    gLabels.polygon((aex-4)+','+(aey+8)+' '+aex+','+aey+' '+(aex+5)+','+(aey+6)).fill('#333');
  }

  // Compute rays
  var R=2*f, Cpt=[cc,0], Qpt=[objX,h];
  var rayData=[];

  // Ray 1: parallel to axis
  var hit1,refl1end,ext1=null;
  if(concave){
    var x1v=R*R-h*h;
    var x1=x1v>0?cc+Math.sqrt(x1v):0;
    hit1=[x1,h]; hit1=clipToArc(hit1);
    var fPt=[-f,0];
    var d1=[fPt[0]-hit1[0],fPt[1]-hit1[1]];
    var l1=Math.sqrt(d1[0]*d1[0]+d1[1]*d1[1]);
    if(l1>0.01){d1=[d1[0]/l1,d1[1]/l1];}else{d1=[0,-1];}
    var rl1=isVirtual?1.8:3.2;
    refl1end=[hit1[0]+d1[0]*rl1,hit1[1]+d1[1]*rl1];
    if(isVirtual) ext1=[hit1,[imgX,hi]];
  } else {
    var x1v2=R*R-h*h;
    var x1b=x1v2>0?cc-Math.sqrt(x1v2):0;
    hit1=[x1b,h]; hit1=clipToArc(hit1);
    var fPt1=[f,0];
    var d1b=[hit1[0]-fPt1[0],hit1[1]-fPt1[1]];
    var l1b=Math.sqrt(d1b[0]*d1b[0]+d1b[1]*d1b[1]);
    if(l1b>0.01){d1b=[d1b[0]/l1b,d1b[1]/l1b];}else{d1b=[-1,0];}
    refl1end=[hit1[0]+d1b[0]*2.8,hit1[1]+d1b[1]*2.8];
    ext1=[hit1,[imgX,hi]];
  }
  rayData.push({inc:[Qpt,hit1],refl:[hit1,refl1end],ext:ext1,labelPos:[(objX+hit1[0])/2,h+0.35]});

  // Ray 2: through F
  var hit2,refl2end,ext2=null;
  var fPt2=concave?[-f,0]:[f,0];
  var d2=[fPt2[0]-Qpt[0],fPt2[1]-Qpt[1]];
  hit2=rayCircleHit(Qpt,d2,Cpt,R);
  if(!hit2){
    var h2y=concave?h*f/(f-do_):h*f/(f+do_);
    hit2=[0,h2y];
  }
  hit2=clipToArc(hit2);
  if(concave){
    refl2end=[hit2[0]-3.2,hit2[1]];
    if(isVirtual){refl2end=[hit2[0]-1.8,hit2[1]];ext2=[hit2,[imgX,hi]];}
  } else {
    refl2end=[hit2[0]-2.8,hit2[1]];
    ext2=[hit2,[imgX,hi]];
  }
  rayData.push({inc:[Qpt,hit2],refl:[hit2,refl2end],ext:ext2,labelPos:[objX*0.5,h*0.65]});

  // Ray 3: through C
  var hit3,refl3end,ext3=null;
  var d3=[cc-Qpt[0],0-Qpt[1]];
  hit3=rayCircleHit(Qpt,d3,Cpt,R);
  if(!hit3){
    var h3y=concave?2*h*f/(2*f-do_):2*h*f/(2*f+do_);
    hit3=[0,h3y];
  }
  hit3=clipToArc(hit3);
  var d3r=[Qpt[0]-hit3[0],Qpt[1]-hit3[1]];
  var l3=Math.sqrt(d3r[0]*d3r[0]+d3r[1]*d3r[1]);
  if(l3>0.01){d3r=[d3r[0]/l3,d3r[1]/l3];}else{d3r=[-1,0];}
  var rl3=isVirtual?1.5:Math.min(3.5,do_*1.1);
  refl3end=[hit3[0]+d3r[0]*rl3,hit3[1]+d3r[1]*rl3];
  if(isVirtual) ext3=[hit3,[imgX,hi]];
  rayData.push({inc:[Qpt,hit3],refl:[hit3,refl3end],ext:ext3,labelPos:[(objX+hit3[0])*0.38,h*0.9]});

  // Ray 4: to V
  var hit4=[0,0];
  var d4=[-do_,-h];
  var l4=Math.sqrt(d4[0]*d4[0]+d4[1]*d4[1]);
  d4=[d4[0]/l4,d4[1]/l4];
  var rl4=isVirtual?1.8:3.0;
  var refl4end=[d4[0]*rl4,d4[1]*rl4];
  var ext4=isVirtual?[hit4,[imgX,hi]]:null;
  rayData.push({inc:[Qpt,hit4],refl:[hit4,refl4end],ext:ext4,labelPos:[objX*0.45,-h*0.45]});

  // Draw rays
  var rayColors=['#1a7abf','#cc2222','#7744aa','#55aa33'];
  for(var r=0;r<4;r++){
    var rd=rayData[r];
    var col=rayColors[r];
    var alpha=1,lw=2.4;
    if(state.highlightRay>0){
      if(state.highlightRay===r+1){alpha=1;lw=3.5;}
      else{alpha=0.13;lw=1.2;}
    }
    var grp=gRays.group().opacity(alpha);

    grp.line(sx(rd.inc[0][0]),sy(rd.inc[0][1]),sx(rd.inc[1][0]),sy(rd.inc[1][1]))
      .stroke({color:col,width:lw});
    drawArrow(grp,rd.inc[0],rd.inc[1],col,lw);

    if(rd.refl){
      grp.line(sx(rd.refl[0][0]),sy(rd.refl[0][1]),sx(rd.refl[1][0]),sy(rd.refl[1][1]))
        .stroke({color:col,width:lw});
      drawArrow(grp,rd.refl[0],rd.refl[1],col,lw);
    }
    if(rd.ext){
      grp.line(sx(rd.ext[0][0]),sy(rd.ext[0][1]),sx(rd.ext[1][0]),sy(rd.ext[1][1]))
        .stroke({color:col,width:lw*0.7,'stroke-dasharray':'7,5'});
    }

    var lp=rd.labelPos;
    var lbl=grp.text(''+(r+1)).attr({x:sx(lp[0]),y:sy(lp[1]),'font-size':16,'font-weight':'bold',fill:col});
    lbl.css('cursor','pointer');
    lbl.on('click',function(rr){return function(){
      state.highlightRay=(state.highlightRay===rr+1)?0:rr+1;
      document.getElementById('rayHighlightInput').value=state.highlightRay;
      drawAll();
    };}(r));
  }

  // Right-angle mark at ray 3 hit point
  var r3h=rayData[2].inc[1];
  // Compute the incident ray direction at hit point
  var incDir=[r3h[0]-Qpt[0], r3h[1]-Qpt[1]];
  var incLen=Math.sqrt(incDir[0]*incDir[0]+incDir[1]*incDir[1]);
  if(incLen>0.01){incDir=[incDir[0]/incLen, incDir[1]/incLen];}
  // Mirror normal at hit point (pointing toward center for concave, away for convex)
  var normDir=[r3h[0]-cc, r3h[1]-0];
  var normLen=Math.sqrt(normDir[0]*normDir[0]+normDir[1]*normDir[1]);
  if(normLen>0.01){normDir=[normDir[0]/normLen, normDir[1]/normLen];}
  if(concave){normDir=[-normDir[0],-normDir[1]];} // normal points toward center (inward)

  var sqSize=0.14;
  // Square corner points: from hit point, go along incident dir and normal dir
  var sqP1=[r3h[0]+incDir[0]*sqSize, r3h[1]+incDir[1]*sqSize];
  var sqP2=[sqP1[0]+normDir[0]*sqSize, sqP1[1]+normDir[1]*sqSize];
  var sqP3=[r3h[0]+normDir[0]*sqSize, r3h[1]+normDir[1]*sqSize];
  var sqStr2=sx(sqP1[0])+','+sy(sqP1[1])+' '+sx(sqP2[0])+','+sy(sqP2[1])+' '+sx(sqP3[0])+','+sy(sqP3[1]);
  gRays.polyline(sqStr2).fill('none').stroke({color:'#333',width:1.4});

  // Eye - positioned below axis between P and C region, with eyelash detail
  var eyeWorldX = concave ? (objX + cX)/2 : objX*0.5;
  var eyeWorldY = -2.1;
  drawEye(sx(eyeWorldX), sy(eyeWorldY));
}

function drawArrow(grp,from,to,col,lw){
  var dx=to[0]-from[0],dy=to[1]-from[1];
  var len=Math.sqrt(dx*dx+dy*dy);
  if(len<0.05)return;
  var ux=dx/len,uy=dy/len;
  var mid=[from[0]+dx*0.55,from[1]+dy*0.55];
  var sz=0.09;
  var px=-uy*sz,py=ux*sz;
  var tip=[mid[0]+ux*sz*1.6,mid[1]+uy*sz*1.6];
  var b1=[mid[0]-ux*sz*0.5+px,mid[1]-uy*sz*0.5+py];
  var b2=[mid[0]-ux*sz*0.5-px,mid[1]-uy*sz*0.5-py];
  grp.polygon(sx(tip[0])+','+sy(tip[1])+' '+sx(b1[0])+','+sy(b1[1])+' '+sx(b2[0])+','+sy(b2[1])).fill(col);
}

function drawEye(ex,ey){
  var s=20;
  // Eye outline - almond shape using two arcs
  var path='M'+(ex-s)+','+ey+' Q'+(ex-s*0.5)+','+(ey-s*0.55)+' '+ex+','+(ey-s*0.35)+' Q'+(ex+s*0.5)+','+(ey-s*0.55)+' '+(ex+s)+','+ey+' Q'+(ex+s*0.5)+','+(ey+s*0.55)+' '+ex+','+(ey+s*0.35)+' Q'+(ex-s*0.5)+','+(ey+s*0.55)+' '+(ex-s)+','+ey+' Z';
  gEye.path(path).fill('#fff').stroke({color:'#333',width:1.8});
  // Pupil
  gEye.circle(s*0.38).cx(ex+s*0.1).cy(ey).fill('#333');
  // Iris highlight
  gEye.circle(s*0.12).cx(ex+s*0.2).cy(ey-s*0.08).fill('#fff');
  // Upper eyelid line
  gEye.path('M'+(ex-s*0.9)+','+(ey-s*0.15)+' Q'+ex+','+(ey-s*0.65)+' '+(ex+s*0.9)+','+(ey-s*0.15))
    .fill('none').stroke({color:'#333',width:2});
  // Eyelashes - radiating from upper lid
  var lashAngles=[-70,-55,-40,-25,-10,5,20];
  for(var i=0;i<lashAngles.length;i++){
    var ang=lashAngles[i]*Math.PI/180;
    var baseX=ex+Math.cos(ang)*s*0.75;
    var baseY=ey-s*0.4+Math.sin(ang)*s*0.15;
    var tipX=baseX+Math.cos(ang-Math.PI/2)*s*0.35;
    var tipY=baseY+Math.sin(ang-Math.PI/2)*s*0.35;
    gEye.line(baseX,baseY,tipX,tipY).stroke({color:'#333',width:1.2,linecap:'round'});
  }
  // Lower lash (single)
  gEye.line(ex-s*0.3,ey+s*0.4,ex-s*0.4,ey+s*0.6).stroke({color:'#333',width:1.2,linecap:'round'});
}

window.toggle_mirrorType=function(on){state.mirrorType=on?'Convex':'Concave';drawAll();};
window.update_objectDistance=function(v){state.objectDistance=v;drawAll();};
window.update_rayHighlight=function(v){state.highlightRay=v;drawAll();};

var steps=[
  {narration:'With the object far from a concave mirror, all four color-coded rays leave the tip Q and truly cross at Q\u2032 in front of the mirror, forming a real, inverted, reduced image between C and F.',state:{mirrorType:'Concave',objectDistance:2.5,highlightRay:0}},
  {narration:'Ray 1 (blue) travels parallel to the axis and reflects straight through F. Click each numbered ray to isolate its single construction rule.',state:{mirrorType:'Concave',objectDistance:2.5,highlightRay:1}},
  {narration:'With the object between F and the mirror, the reflected rays diverge; only their dashed backward extensions meet behind the mirror, producing a virtual, upright, magnified image.',state:{mirrorType:'Concave',objectDistance:0.6,highlightRay:0}},
  {narration:'Convex mirror: F and C move behind the arc, reflected rays always diverge, and their dashed extensions meet at an upright, reduced virtual image behind the mirror.',state:{mirrorType:'Convex',objectDistance:2.5,highlightRay:0}}
];
var curStep=0;

function applyStep(i){
  curStep=i;
  var s=steps[i];
  state.mirrorType=s.state.mirrorType;
  state.objectDistance=s.state.objectDistance;
  state.highlightRay=s.state.highlightRay||0;
  document.getElementById('mirrorTypeInput').checked=(state.mirrorType==='Convex');
  document.getElementById('objectDistanceInput').value=state.objectDistance;
  document.getElementById('objectDistanceVal').value=state.objectDistance;
  document.getElementById('rayHighlightInput').value=state.highlightRay;
  document.getElementById('demoNarration').textContent=s.narration;
  document.getElementById('stepLabel').textContent=(i+1)+'/'+steps.length;
  drawAll();
}
window.prevStep=function(){if(curStep>0)applyStep(curStep-1);};
window.nextStep=function(){if(curStep<steps.length-1)applyStep(curStep+1);};

applyStep(0);
window.__markRendered();
})();
